import 'package:flutter/material.dart';
import 'package:pdf/widgets.dart' as pw;
import 'package:printing/printing.dart';
class Voce { final String nome; final double min; final double max; final double medio; const Voce(this.nome, this.min, this.max) : medio=(min+max)/2; }
const LISTINO=[Voce("Impianto completo 100mq",6000,12000),Voce("Punto luce / comando",20,40),Voce("Presa Unel",35,45),Voce("Salvavita / Citofono",80,180),Voce("Videocitofono",510,900),Voce("Dichiarazione conformita",300,350),];
class Riga{ Voce voce; int qty; double prezzo; Riga(this.voce,this.qty,this.prezzo); double get tot=>qty*prezzo; }
void main()=>runApp(const App());
class App extends StatelessWidget{const App({super.key}); @override Widget build(BuildContext c)=>MaterialApp(home:const Home(),debugShowCheckedModeBanner:false);}
class Home extends StatefulWidget{const Home({super.key}); @override State<Home> createState()=>_HomeState();}
class _HomeState extends State<Home>{
 final cliente=TextEditingController(); final List<Riga> righe=[];
 double get totale=>righe.fold(0,(s,r)=>s+r.tot); double get acconto=>totale*0.4; double get saldo=>totale*0.6;
 Future<void> genPDF() async{final doc=pw.Document();doc.addPage(pw.Page(build:(c)=>pw.Column(crossAxisAlignment:pw.CrossAxisAlignment.start,children:[pw.Text("Bart - Elettrico Pro",style:pw.TextStyle(fontSize:20,fontWeight:pw.FontWeight.bold)),pw.Text("Cliente: ${cliente.text}"),pw.Divider(),...righe.map((r)=>pw.Row(mainAxisAlignment:pw.MainAxisAlignment.spaceBetween,children:[pw.Text("${r.qty}x ${r.voce.nome}"),pw.Text("${r.tot.toStringAsFixed(2)}€")])),pw.Divider(),pw.Text("TOTALE: ${totale.toStringAsFixed(2)}€"),pw.Text("ACCONTO 40%: ${acconto.toStringAsFixed(2)}€"),pw.Text("SALDO 60%: ${saldo.toStringAsFixed(2)}€")])));await Printing.layoutPdf(onLayout:(f)=>doc.save());}
 @override Widget build(BuildContext context){return Scaffold(appBar:AppBar(title:const Text("Bart - Elettrico Pro"),backgroundColor:Colors.orange),body:Column(children:[Padding(padding:const EdgeInsets.all(8),child:TextField(controller:cliente,decoration:const InputDecoration(labelText:"Cliente",border:OutlineInputBorder()))),Expanded(child:ListView.builder(itemCount:LISTINO.length,itemBuilder:(c,i){final v=LISTINO[i];return ListTile(title:Text(v.nome,style:const TextStyle(fontSize:13)),subtitle:Text("${v.min.toInt()}-${v.max.toInt()}€"),trailing:const Icon(Icons.add),onTap:()=>setState(()=>righe.add(Riga(v,1,v.medio))));})),Expanded(child:righe.isEmpty?const Center(child:Text("Nessuna voce")):ListView.builder(itemCount:righe.length,itemBuilder:(c,i){final r=righe[i];return ListTile(title:Text("${r.qty}x ${r.voce.nome}"),subtitle:Slider(value:r.prezzo,min:r.voce.min,max:r.voce.max,onChanged:(val)=>setState(()=>r.prezzo=val)),trailing:Text("${r.tot.toStringAsFixed(0)}€",style:const TextStyle(fontWeight:FontWeight.bold)));})),Container(color:Colors.orange.shade50,padding:const EdgeInsets.all(12),child:Column(children:[Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[const Text("TOTALE"),Text("${totale.toStringAsFixed(2)}€",style:const TextStyle(fontWeight:FontWeight.bold,fontSize:18))]),SizedBox(width:double.infinity,child:ElevatedButton.icon(onPressed:righe.isEmpty?null:genPDF,icon:const Icon(Icons.picture_as_pdf),label:const Text("GENERA PDF")))]))])) ;}
}
